import React from 'react';
import '../styles/MapView.css';

function MapView() {
  return (
    <div className="map-tab">
      <div className="map-buttons">
        <button>Добавить событие на карту</button>
        <button>Поиск событий</button>
        <div className="filter">
          <span>Фильтр</span>
        </div>
      </div>
      
      <div className="map-container" style="position:relative;overflow:hidden;">
        <a href="https://yandex.ru/maps/215/dubna/?utm_medium=mapframe&utm_source=maps" style="color:#eee;font-size:12px;position:absolute;top:0px;">Дубна</a>
        <a href="https://yandex.ru/maps/215/dubna/?ll=37.225414%2C56.740005&utm_medium=mapframe&utm_source=maps&z=14" style="color:#eee;font-size:12px;position:absolute;top:14px;">Яндекс Карты — транспорт, навигация, поиск мест</a>
        <iframe src="https://yandex.ru/map-widget/v1/?ll=37.225414%2C56.740005&z=14" width="560" height="400" frameborder="1" allowfullscreen="true" style="position:relative;">
        </iframe>
      </div>
    </div>
  );
}

export default MapView;
